def cascade_for_trigger(G, trigger_edge, alpha=0.2):
    # Baseline loads and capacities computed on the intact network
    L0 = nx.betweenness_centrality(G, normalized=False)
    C = {n: (1.0 + alpha) * L0.get(n, 0) for n in G.nodes()}

    # Apply LINE trigger
    H = G.copy()
    u, v = trigger_edge
    if H.has_edge(u, v):
        H.remove_edge(u, v)

    # Cascade: repeatedly remove overloaded nodes until stable
    while True:
        if H.number_of_nodes() == 0:
            break
        L = nx.betweenness_centrality(H, normalized=False)
        overloaded = [n for n in H.nodes() if L.get(n, 0) > C.get(n, 0)]
        if not overloaded:
            break
        H.remove_nodes_from(overloaded)

    # Determine size of the largest surviving connected component
    if H.number_of_nodes() == 0:
        largest = 0
    else:
        largest = max(len(comp) for comp in nx.connected_components(H))
    return largest

